import torch
import torch.nn as nn
import math
from torch.utils.cpp_extension import load_inline

conv_transpose3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int N, int C_in, int D_in, int H_in, int W_in,
    int C_out, int D_out, int H_out, int W_out,
    int kD, int kH, int kW,
    int stride, int padding,
    int groups)
{
    extern __shared__ float sw[];
    int oc_n_idx = blockIdx.y;
    int n = oc_n_idx / C_out;
    int oc = oc_n_idx % C_out;
    int C_in_per_group = C_in / groups;
    int C_out_per_group = C_out / groups;
    int g = oc / C_out_per_group;
    int oc_local = oc % C_out_per_group;
    int kDHW = kD * kH * kW;
    int weight_size = C_in_per_group * kDHW;
    for (int i = threadIdx.x; i < weight_size; i += blockDim.x) {
        int ic_local = i / kDHW;
        int rem = i % kDHW;
        int kd = rem / (kH * kW);
        int rem2 = rem % (kH * kW);
        int kh = rem2 / kW;
        int kw = rem2 % kW;
        long widx = (((long)(g * C_in_per_group + ic_local) * C_out_per_group + oc_local) * kD + kd) * kH;
        widx = (widx + kh) * kW + kw;
        sw[i] = weight[widx];
    }
    __syncthreads();
    float bias_val = bias ? bias[oc] : 0.0f;
    const int TILE_W = 8;
    int W_tiles = (W_out + TILE_W - 1) / TILE_W;
    long spatial_total = (long)D_out * H_out * W_tiles;
    for (long idx = (long)blockIdx.x * blockDim.x + threadIdx.x;
         idx < spatial_total;
         idx += (long)blockDim.x * gridDim.x) {
        int wt = (int)(idx % W_tiles);
        long tmp = idx / W_tiles;
        int oh = (int)(tmp % H_out);
        tmp /= H_out;
        int od = (int)tmp;
        int ow_base = wt * TILE_W;
        float val[TILE_W];
        #pragma unroll
        for (int e = 0; e < TILE_W; ++e) val[e] = bias_val;
        for (int ic_local = 0; ic_local < C_in_per_group; ++ic_local) {
            int ic = g * C_in_per_group + ic_local;
            int base_ic = ic_local * kDHW;
            for (int kd = 0; kd < kD; ++kd) {
                int id_nom = od + padding - kd;
                if (id_nom % stride != 0) continue;
                int id = id_nom / stride;
                if (id < 0 || id >= D_in) continue;
                for (int kh = 0; kh < kH; ++kh) {
                    int ih_nom = oh + padding - kh;
                    if (ih_nom % stride != 0) continue;
                    int ih = ih_nom / stride;
                    if (ih < 0 || ih >= H_in) continue;
                    long input_base = (((long)n * C_in + ic) * D_in + id) * H_in;
                    input_base = (input_base + ih) * W_in;
                    int widx_base = base_ic + (kd * kH + kh) * kW;
                    for (int kw = 0; kw < kW; ++kw) {
                        float wv = sw[widx_base + kw];
                        #pragma unroll
                        for (int e = 0; e < TILE_W; ++e) {
                            int ow = ow_base + e;
                            if (ow >= W_out) continue;
                            int iw_nom = ow + padding - kw;
                            if (iw_nom % stride != 0) continue;
                            int iw = iw_nom / stride;
                            if (iw < 0 || iw >= W_in) continue;
                            val[e] += input[input_base + iw] * wv;
                        }
                    }
                }
            }
        }
        long output_base = (((long)n * C_out + oc) * D_out + od) * H_out;
        output_base = (output_base + oh) * W_out;
        #pragma unroll
        for (int e = 0; e < TILE_W; ++e) {
            int ow = ow_base + e;
            if (ow < W_out) {
                output[output_base + ow] = val[e];
            }
        }
    }
}
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups)
{
    input = input.contiguous();
    weight = weight.contiguous();
    int N = input.size(0);
    int C_in = input.size(1);
    int D_in = input.size(2);
    int H_in = input.size(3);
    int W_in = input.size(4);
    int C_out_per_group = weight.size(1);
    int C_out = C_out_per_group * groups;
    int kD = weight.size(2);
    int kH = weight.size(3);
    int kW = weight.size(4);
    int D_out = (D_in - 1) * stride - 2 * padding + kD + output_padding;
    int H_out = (H_in - 1) * stride - 2 * padding + kH + output_padding;
    int W_out = (W_in - 1) * stride - 2 * padding + kW + output_padding;
    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());
    const float* bias_ptr = nullptr;
    torch::Tensor bias_contig;
    if (bias.defined() && bias.numel() > 0) {
        bias_contig = bias.contiguous();
        bias_ptr = bias_contig.data_ptr<float>();
    }
    int C_in_per_group = C_in / groups;
    int weight_size_per_oc = C_in_per_group * kD * kH * kW;
    size_t shared_mem_bytes = (size_t)weight_size_per_oc * sizeof(float);
    int TILE_W_host = 8;
    int W_tiles_host = (W_out + TILE_W_host - 1) / TILE_W_host;
    long spatial_total = (long)D_out * H_out * W_tiles_host;
    int threads = 256;
    long blocks_x_l = (spatial_total + threads - 1) / threads;
    int blocks_x = (int)(blocks_x_l > 1024 ? 1024 : blocks_x_l);
    if (blocks_x < 1) blocks_x = 1;
    int blocks_y = N * C_out;
    dim3 grid(blocks_x, blocks_y);
    conv_transpose3d_kernel<<<grid, threads, shared_mem_bytes>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        N, C_in, D_in, H_in, W_in,
        C_out, D_out, H_out, W_out,
        kD, kH, kW,
        stride, padding,
        groups
    );
    return output;
}
"""

conv_transpose3d_cpp_source = r"""
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups);
"""

conv_transpose3d_module = load_inline(
    name="conv_transpose3d_module",
    cpp_sources=conv_transpose3d_cpp_source,
    cuda_sources=conv_transpose3d_source,
    functions=["conv_transpose3d_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: int, stride: int = 1,
                 padding: int = 0, output_padding: int = 0, groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = stride
        self.padding = padding
        self.output_padding = output_padding
        self.groups = groups
        self.use_bias = bias

        self.weight = nn.Parameter(torch.empty(
            in_channels, out_channels // groups, kernel_size, kernel_size, kernel_size
        ))

        if bias:
            self.bias = nn.Parameter(torch.empty(out_channels))
        else:
            self.register_parameter('bias', None)

        self.reset_parameters()

    def reset_parameters(self):
        n = self.in_channels * (self.kernel_size ** 3)
        stdv = 1.0 / math.sqrt(n)
        nn.init.uniform_(self.weight, -stdv, stdv)
        if self.bias is not None:
            nn.init.uniform_(self.bias, -stdv, stdv)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous().cuda().float()
        weight = self.weight.contiguous().cuda().float()
        bias = self.bias.contiguous().cuda().float() if self.bias is not None else torch.tensor([], device=x.device, dtype=torch.float32)

        return conv_transpose3d_module.conv_transpose3d_cuda(
            x, weight, bias,
            self.stride, self.padding, self.output_padding, self.groups
        )

